parameters.jsCode:
// Rate-limit alerts to at most one per hour.
// Since 2026-07-28 the catch-up fires 4x/hour, so a persistent failure (dead network at
// 09:30, or a wedged Code-node task runner) would otherwise fire ~60 Telegram messages a
// day. Send the first one, swallow the rest, and report the count on the next real send so
// nothing is silently lost.
const WINDOW_MS = 60 * 60 * 1000;
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const last = Number(sd.lastAlertAt) || 0;

if (now - last < WINDOW_MS) {
  sd.suppressedCount = (Number(sd.suppressedCount) || 0) + 1;
  console.log('Alert suppressed (' + sd.suppressedCount + ' since last send)');
  return [];
}

const swallowed = Number(sd.suppressedCount) || 0;
sd.lastAlertAt = now;
sd.suppressedCount = 0;
const items = $input.all();
for (const it of items) { it.json.suppressedSinceLast = swallowed; }
console.log('Alert sending (' + swallowed + ' suppressed since last send)');
return items;
